import * as prettier from 'prettier';
import { createUniqueIdentifiers } from '../utils';
import type { ResolvedExtension } from '../types';

export const GENERATED_HEADER = [
  '// AUTO-GENERATED by `bigcapital extensions sync`. Do not edit by hand.',
  '// Edit bigcapital.extensions.json and run `pnpm extensions:sync`.',
].join('\n');

export async function formatGeneratedFile(content: string): Promise<string> {
  return prettier.format(content, {
    parser: 'typescript',
    singleQuote: true,
    trailingComma: 'all',
    printWidth: 80,
  });
}

export interface ImportLines {
  extensions: ResolvedExtension[];
  identifiers: Map<string, string>;
  imports: string[];
}

export function buildImportLines(
  extensions: ResolvedExtension[],
  subpath: 'server' | 'web',
  suffix: string,
): ImportLines {
  const included = extensions
    .filter((extension) =>
      subpath === 'server' ? extension.hasServer : extension.hasWeb,
    )
    .sort((a, b) => a.packageName.localeCompare(b.packageName));

  const identifiers = createUniqueIdentifiers(
    included.map((extension) => extension.packageName),
    suffix,
  );

  const imports = included.map(
    (extension) =>
      `import { extension as ${identifiers.get(
        extension.packageName,
      )} } from '${extension.packageName}/${subpath}';`,
  );

  return { extensions: included, identifiers, imports };
}
